.column.over { outline: 2px dashed var(--accent); outline-offset: -2px; }
.pill { display: block; width: fit-content; margin-top: 4px; padding: 1px 8px; border-radius: 999px; color: #fff; font-size: .75rem; font-weight: 600; }
#search-bar { display: flex; gap: 8px; margin-top: 10px; }
#search-bar input { flex: 1; max-width: 320px; }
#filter-bar, #assignee-filter-bar { display: flex; gap: 6px; margin-top: 10px; flex-wrap: wrap; }
#filter-bar .filter, #assignee-filter-bar .filter { background: transparent; color: var(--text); border: 2px solid var(--c, var(--accent)); border-radius: 999px; padding: 3px 12px; font-weight: 500; }
#filter-bar .filter.active, #assignee-filter-bar .filter.active { background: var(--c, var(--accent)); color: #fff; }
.avatar { flex: none; width: 28px; height: 28px; border-radius: 50%; background: var(--accent); color: #0f1115; display: inline-flex; align-items: center; justify-content: center; font-size: .75rem; font-weight: 700; margin-left: auto; }
.card .actions { display: flex; align-items: center; gap: 4px; }
@media (max-width: 900px) { #board { grid-template-columns: 1fr; padding: 12px; } }
#toast {
  position: fixed; bottom: 24px; left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: #1b1e26; color: #fff; border: 1px solid #8b7cf6;
  border-radius: 10px; padding: 10px 18px; opacity: 0;
  pointer-events: none; transition: opacity .2s, transform .2s; z-index: 1000;
}
#toast.show { opacity: 1; transform: translateX(-50%); }

@media (max-width: 700px) {
  header { padding: 12px; }
  form > * { flex: 1 1 100%; }
  input, select, button { min-height: 44px; }
}

